mapper.select:
SELECT 
FROM tb_transport_order t
WHERE t.row_valid = 1
AND t.source_system = #{sourceSystem}
AND t.source_order_no = #{sourceOrderNo}

SELECT 
FROM tb_transport_order t
WHERE t.row_valid = 1

    AND t.order_num = #{orderNum}


    AND t.state = #{state}


    AND t.carrier_code = #{carrierCode}


    AND (t.dispatch_logistics_node_code = #{nodeCode} OR t.handover_logistics_node_code = #{nodeCode})


    AND t.create_time >= #{beginTime}


    AND t.create_time <= #{endTime}

ORDER BY t.id DESC

SELECT t.order_num FROM tb_transport_order t WHERE t.row_valid = 1 AND t.state IN
#{state}
ORDER BY t.id ASC LIMIT #{limit}
